def max_produce_window(produce, k):
    n = len(produce)
    max_sum = 0
    for i in range(n - k + 1):
        window_sum = 0
        for j in range(i, i + k):
            window_sum += produce[j]
        max_sum = max(max_sum, window_sum)
    return max_sum

def count_route_segments(distances, target):
    n = len(distances)
    count = 0
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += distances[j]
            if curr_sum == target:
                count += 1
    return count

def longest_section(items, k):
    n = len(items)
    max_len = 0
    for i in range(n):
        freq = {}
        for j in range(i, n):
            freq[items[j]] = freq.get(items[j], 0) + 1
            if len(freq) > k:
                break
            max_len = max(max_len, j - i + 1)
    return max_len
